name: flow_grain
description: Bounded scrolling fluid tiles, world-space grain, velocity strokes and
  motion correspondence. Normal launch/stop; frame-boundary reset; existing profiling
  timeline.
operations:
- create:
    box: flow_renderer
    name: 1. Renderer — launch / stop
    frame:
      x: 80.0
      y: 80.0
      w: 370.0
      h: 100.0
    properties:
      code: |
        import afield.graphics.vulkan.util.Options

        prop<Window>(window)
        prop<Renderer>(renderer)
        Options.enableHDR = false
        Options.profiling = false // GPU timings remain in Field's existing renderer profiler.
        once.renderer {
            window = Window("Flow grain playground", initialDimensions = Rect(80.0, 80.0, 960.0, 720.0))
